--
-- Table structure for table `watch_rule`
--

DROP TABLE IF EXISTS `watch_rule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `watch_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `rule_name` varchar(128) NOT NULL,
  `market_hash_name` varchar(255) NOT NULL,
  `wear_bucket` tinyint DEFAULT NULL,
  `float_min` decimal(10,8) DEFAULT NULL,
  `float_max` decimal(10,8) DEFAULT NULL,
  `max_price` bigint DEFAULT NULL COMMENT '心理价位，单位：分',
  `discount_pct` decimal(5,2) DEFAULT NULL COMMENT '低于近7日基准的折扣阈值，百分比',
  `relative_gap_pct` decimal(5,2) NOT NULL DEFAULT '3.00' COMMENT '相对闸：最低到手价比第二低至少高出的百分比',
  `filter_json` json DEFAULT NULL COMMENT '排除条件：印花、改名、关键词等',
  `cooldown_sec` int NOT NULL DEFAULT '600',
  `daily_limit` int NOT NULL DEFAULT '20',
  `min_sample` int NOT NULL DEFAULT '30' COMMENT '基准最少样本数，少于这个数不判定',
  `merge_window_sec` int NOT NULL DEFAULT '120' COMMENT '同款多条命中合并窗口，单位秒',
  `enabled` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rule_name` (`rule_name`),
  KEY `idx_mhn` (`market_hash_name`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='监控规则';
/*!40101 SET character_set_client = @saved_cs_client */;

